import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { API_BASE_URL } from '../../../config';

export default function AdminLoginPage() {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const router = useRouter();

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        try {
            const res = await fetch(`${API_BASE_URL}/api/admin/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, password }),
            });
            const data = await res.json();

            if (!res.ok) {
                throw new Error(data.message || 'Invalid admin credentials');
            }

            localStorage.setItem('adminToken', data.token);
            router.push('/admin/dashboard');
        } catch (err: any) {
            console.error("Admin login error:", err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen px-4 bg-slate-950">
            <div className="glass-panel w-full max-w-md p-10 animate-fade-in relative overflow-hidden border-red-500/20">
                <div className="absolute top-[-50px] right-[-50px] w-40 h-40 bg-red-500/10 rounded-full blur-[50px] pointer-events-none"></div>
                
                <div className="text-center mb-10 relative z-10">
                    <h2 className="text-3xl font-bold text-white mb-2" style={{ fontFamily: 'var(--font-outfit)' }}>Admin Access</h2>
                    <p className="text-slate-400 text-sm">Restricted Area. Authorized Personnel Only.</p>
                </div>

                {error && <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-lg mb-6 text-sm relative z-10">{error}</div>}

                <form onSubmit={handleSubmit} className="space-y-6 relative z-10">
                    <div>
                        <label className="block text-sm font-medium text-slate-300 mb-2">Admin Email</label>
                        <input
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-lg px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:ring-2 focus:ring-red-500/50 transition-all shadow-inner"
                            placeholder="admin@example.com"
                            required
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-300 mb-2">Password</label>
                        <input
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 rounded-lg px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:ring-2 focus:ring-red-500/50 transition-all shadow-inner"
                            placeholder="â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢"
                            required
                        />
                    </div>

                    <button disabled={loading} type="submit" className="w-full bg-gradient-to-r from-red-600 to-rose-700 hover:from-red-500 hover:to-rose-600 text-white font-semibold py-3 px-4 rounded-lg shadow-[0_0_20px_rgba(220,38,38,0.2)] transition-all duration-300 disabled:opacity-50">
                        {loading ? 'Authenticating...' : 'Enter System'}
                    </button>
                </form>
            </div>
        </div>
    );
}

﻿"use client";
import { useEffect, useState } from 'react';
import { API_BASE_URL } from '../../../config';
import Pagination from '../../../components/Pagination';
import Link from 'next/link';

interface Interaction {
    _id: string;
    website: { url: string };
    user: { name: string; email: string };
    seoScore: number;
    technicalScore: number;
    performanceScore: number;
    status: string;
    createdAt: string;
}

export default function AllReportsPage() {
    const [reports, setReports] = useState<Interaction[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [totalPages, setTotalPages] = useState(1);
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearch, setDebouncedSearch] = useState('');

    // Handle debounced search
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearch(searchTerm);
        }, 500);
        return () => clearTimeout(timer);
    }, [searchTerm]);

    const fetchReports = async (page = 1, search = '') => {
        try {
            console.log(`[Admin Feed] Fetching Page: ${page}, Search: "${search}"`);
            setLoading(true);
            const token = localStorage.getItem('adminToken');
            const res = await fetch(`${API_BASE_URL}/api/admin/reports?page=${page}&limit=10&search=${search}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });

            if (!res.ok) throw new Error('Failed to fetch platform interaction history');

            const data = await res.json();
            
            // Handle both new paginated object and old array response
            if (data && data.reports && Array.isArray(data.reports)) {
                setReports(data.reports);
                setTotalPages(data.totalPages || 1);
                setCurrentPage(data.currentPage || 1);
            } else if (Array.isArray(data)) {
                setReports(data);
                setTotalPages(1);
                setCurrentPage(1);
            } else {
                setReports([]);
            }
        } catch (err: any) {
            setError(err.message);
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchReports(1, debouncedSearch);
    }, [debouncedSearch]);

    if (loading) return <div className="text-slate-400">Loading systemic interaction history...</div>;
    if (error) return <div className="text-red-400 bg-red-500/10 p-4 rounded-lg border border-red-500/20">{error}</div>;

    return (
        <div className="space-y-10 animate-fade-in">
            <header>
                <h1 className="text-3xl font-bold text-white mb-2" style={{ fontFamily: 'var(--font-outfit)' }}>System Logs</h1>
                <p className="text-slate-400">A comprehensive history of every SEO audit performed within the platform.</p>
            </header>

            <div className="relative max-w-md w-full">
                <svg className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
                <input 
                    type="text" 
                    placeholder="Search by URL, Name or Email..." 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-2.5 pl-10 pr-4 text-sm text-white placeholder:text-slate-600 focus:outline-none focus:border-red-500/50 transition-all"
                />
                {loading && (
                    <div className="absolute right-4 top-1/2 -translate-y-1/2">
                        <div className="w-4 h-4 border-2 border-red-500/20 border-t-red-500 rounded-full animate-spin"></div>
                    </div>
                )}
            </div>

            <section className={`glass-panel p-8 border-slate-800/50 transition-opacity ${loading && debouncedSearch === searchTerm ? 'opacity-50' : 'opacity-100'}`}>
                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="border-b border-slate-800/50 text-slate-500 text-xs uppercase tracking-wider">
                                <th className="py-4 px-4 font-medium">User Account</th>
                                <th className="py-4 px-4 font-medium">Website Target</th>
                                <th className="py-4 px-4 font-medium">Scores (S/T/P)</th>
                                <th className="py-4 px-4 font-medium">Audit Timestamp</th>
                                <th className="py-4 px-4 font-medium text-right">Status</th>
                            </tr>
                        </thead>
                        <tbody className="text-sm text-slate-300">
                            {reports.map(report => (
                                <tr key={report._id} className="border-b border-slate-900/50 hover:bg-white/[0.02] transition-colors group">
                                    <td className="py-5 px-4 font-medium text-white">{report.user?.name || "Anonymous User"} <span className="text-xs font-normal text-slate-500 block">{report.user?.email}</span></td>
                                    <td className="py-5 px-4">
                                        <Link 
                                            href={`/admin/reports/view?id=${report._id}`}
                                            className="text-blue-400 font-mono text-xs opacity-80 decoration-slate-600 underline-offset-4 hover:underline hover:opacity-100 transition-all"
                                        >
                                            {report.website?.url || "N/A"}
                                        </Link>
                                    </td>
                                    <td className="py-5 px-4">
                                        <div className="flex gap-2">
                                            <ScoreBadge score={report.seoScore} />
                                            <ScoreBadge score={report.technicalScore} />
                                            <ScoreBadge score={report.performanceScore} />
                                        </div>
                                    </td>
                                    <td className="py-5 px-4 text-slate-500 text-xs">
                                        {new Date(report.createdAt).toLocaleString()}
                                    </td>
                                    <td className="py-5 px-4 text-right">
                                        <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-tighter ${report.status === 'completed' ? 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20' : 'bg-amber-500/10 text-amber-500 border border-amber-500/20'}`}>
                                            {report.status}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>

                    {reports.length === 0 && !loading && (
                        <div className="py-20 text-center">
                            <div className="text-4xl mb-4">ðŸ”</div>
                            <h3 className="text-white font-bold mb-2">No Reports Found</h3>
                            <p className="text-slate-500 text-sm">We couldn't find any activities matching "{debouncedSearch}"</p>
                            <button 
                                onClick={() => setSearchTerm('')}
                                className="mt-6 text-red-400 hover:text-red-300 text-sm font-bold underline underline-offset-4"
                            >
                                Clear Search
                            </button>
                        </div>
                    )}
                </div>

                <Pagination 
                    currentPage={currentPage}
                    totalPages={totalPages}
                    onPageChange={(page) => fetchReports(page, debouncedSearch)}
                />
            </section>
        </div>
    );
}

function ScoreBadge({ score }: { score: number }) {
    const color = score >= 80 ? 'text-emerald-400' : score >= 50 ? 'text-amber-400' : 'text-red-400';
    return (
        <span className={`w-8 h-8 flex items-center justify-center rounded-lg bg-slate-900 border border-slate-800 text-[10px] font-bold ${color}`}>
            {score}
        </span>
    );
}

﻿"use client";
import { useEffect, useState, use } from 'react';
import { API_BASE_URL } from '../../../../config';
import Link from 'next/link';

export default function AdminReportClient({ id }: { id: string }) {
    const [report, setReport] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');

    useEffect(() => {
        const fetchReport = async () => {
            try {
                const token = localStorage.getItem('adminToken');
                const res = await fetch(`${API_BASE_URL}/api/reports/${id}`, {
                    headers: { Authorization: `Bearer ${token}` }
                });
                if (!res.ok) throw new Error('Failed to fetch report');
                const data = await res.json();
                setReport(data);
            } catch (err: any) {
                setError(err.message);
            } finally {
                setLoading(false);
            }
        };
        fetchReport();
    }, [id]);

    if (loading) return <div className="p-8 text-center text-slate-400 animate-pulse">Loading detailed diagnostic auditâ€¦</div>;
    if (error || !report) return <div className="p-8 text-center text-red-400">Error: {error || 'Report not found'}</div>;

    return (
        <div className="w-full max-w-6xl mx-auto animate-fade-in relative z-10">
            <header className="mb-8">
                <Link prefetch={false} href="/admin/reports" className="text-slate-500 hover:text-white transition-colors flex items-center gap-2 text-sm font-medium mb-4">
                    â† Back to Logs
                </Link>
                <h1 className="text-3xl font-bold text-white">Diagnostic Report for {id}</h1>
                <p className="text-blue-400 underline">{report.website?.url}</p>
            </header>
            <div className="glass-panel p-6 border-slate-800/50">
                 <pre className="text-xs text-slate-500">{JSON.stringify(report, null, 2)}</pre>
            </div>
        </div>
    );
}

﻿"use client";
import { useEffect, useState } from 'react';
import { API_BASE_URL } from '../../../config';

interface User {
    _id: string;
    name: string;
    email: string;
    mobile: string;
    countryCode?: string;
    plan: string;
    pendingPlanType?: string | null;
    receiptUrl?: string | null;
    planStatus?: string;
    createdAt: string;
}

interface HistoryEntry {
    _id: string;
    userName: string;
    userEmail: string;
    previousPlan: string;
    requestedPlan: string;
    status: 'approved' | 'rejected';
    receiptUrl: string;
    createdAt: string;
}

export default function UpgradeRequestsPage() {
    const [users, setUsers] = useState<User[]>([]);
    const [history, setHistory] = useState<HistoryEntry[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');

    const fetchRequests = async () => {
        try {
            const token = localStorage.getItem('adminToken');
            const res = await fetch(`${API_BASE_URL}/api/admin/users`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });

            if (!res.ok) throw new Error('Failed to fetch upgrade requests');

            const data: User[] = await res.json();
            // Filter for only pending requests
            const pendingRequests = data.filter(user => user.planStatus === 'pending');
            setUsers(pendingRequests);
        } catch (err: any) {
            setError(err.message);
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const fetchHistory = async () => {
        try {
            const token = localStorage.getItem('adminToken');
            const res = await fetch(`${API_BASE_URL}/api/admin/upgrade-history`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });

            if (!res.ok) {
                console.error('Failed to fetch upgrade history:', res.status);
                return;
            }

            const data: HistoryEntry[] = await res.json();
            setHistory(data);
        } catch (err: any) {
            console.error(err);
        }
    };

    const handleApprovePlan = async (userId: string) => {
        if (!confirm('Are you sure you want to approve this plan upgrade?')) return;
        try {
            const token = localStorage.getItem('adminToken');
            const res = await fetch(`${API_BASE_URL}/api/admin/users/${userId}/approve-plan`, {
                method: 'PUT',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (!res.ok) throw new Error('Failed to approve plan');
            alert('Plan approved successfully');
            fetchRequests();
            fetchHistory();
        } catch (err) {
            console.error(err);
            alert('Failed to approve plan');
        }
    };

    const handleRejectPlan = async (userId: string) => {
        if (!confirm('Are you sure you want to reject this plan upgrade?')) return;
        try {
            const token = localStorage.getItem('adminToken');
            const res = await fetch(`${API_BASE_URL}/api/admin/users/${userId}/reject-plan`, {
                method: 'PUT',
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (!res.ok) throw new Error('Failed to reject plan');
            alert('Plan request rejected');
            fetchRequests();
            fetchHistory();
        } catch (err) {
            console.error(err);
            alert('Failed to reject plan');
        }
    };

    useEffect(() => {
        fetchRequests();
        fetchHistory();
    }, []);

    if (loading) return <div className="text-slate-400">Loading upgrade requests...</div>;
    if (error) return <div className="text-red-400 bg-red-500/10 p-4 rounded-lg border border-red-500/20">{error}</div>;

    return (
        <div className="space-y-10 animate-fade-in">
            <header>
                <h1 className="text-3xl font-bold text-white mb-2" style={{ fontFamily: 'var(--font-outfit)' }}>Upgrade Requests & PDF Verification</h1>
                <p className="text-slate-400">Manage all pending plan upgrade requests and verify payment proofs.</p>
            </header>

            {users.length === 0 ? (
                <div className="glass-panel p-12 text-center border-slate-800/50">
                    <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-500">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                    <h3 className="text-lg font-medium text-white mb-1">Inbox Clean!</h3>
                    <p className="text-slate-500 text-sm">No pending upgrade requests at the moment.</p>
                </div>
            ) : (
                <section className="glass-panel p-8 border-slate-800/50">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="border-b border-slate-800/50 text-slate-500 text-xs uppercase tracking-wider">
                                    <th className="py-4 px-4 font-medium">User</th>
                                    <th className="py-4 px-4 font-medium">Current Plan</th>
                                    <th className="py-4 px-4 font-medium">Requested Plan</th>
                                    <th className="py-4 px-4 font-medium">Payment Proof</th>
                                    <th className="py-4 px-4 font-medium text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="text-sm text-slate-300">
                                {users.map(user => (
                                    <tr key={user._id} className="border-b border-slate-900/50 hover:bg-white/[0.02] transition-colors group">
                                        <td className="py-5 px-4 font-medium text-white">
                                            <div className="flex flex-col">
                                                <span>{user.name}</span>
                                                <span className="text-[10px] text-slate-500 font-mono">{user.email}</span>
                                            </div>
                                        </td>
                                        <td className="py-5 px-4">
                                            <span className="px-2 py-1 rounded text-[10px] font-bold uppercase bg-slate-500/10 text-slate-400 border border-slate-500/20">
                                                {user.plan}
                                            </span>
                                        </td>
                                        <td className="py-5 px-4">
                                            <span className="px-2 py-1 rounded text-[10px] font-bold uppercase bg-amber-500/10 text-amber-500 border border-amber-500/20">
                                                {user.pendingPlanType}
                                            </span>
                                        </td>
                                        <td className="py-5 px-4">
                                            <a 
                                                href={`${API_BASE_URL}${user.receiptUrl}`} 
                                                target="_blank" 
                                                rel="noopener noreferrer"
                                                className="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg bg-blue-600/10 text-blue-400 border border-blue-500/20 hover:bg-blue-600/20 transition-all font-bold text-[10px]"
                                            >
                                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                                                </svg>
                                                VIEW PDF/IMG
                                            </a>
                                        </td>
                                        <td className="py-5 px-4 text-right">
                                            <div className="flex items-center justify-end gap-3">
                                                <button 
                                                    onClick={() => handleApprovePlan(user._id)} 
                                                    className="px-3 py-1.5 rounded bg-green-600 text-white font-bold text-[10px] hover:bg-green-500 transition-all shadow-lg shadow-green-900/20"
                                                >
                                                    APPROVE
                                                </button>
                                                <button 
                                                    onClick={() => handleRejectPlan(user._id)} 
                                                    className="px-3 py-1.5 rounded bg-slate-800 text-slate-400 font-bold text-[10px] hover:bg-red-600 hover:text-white transition-all"
                                                >
                                                    REJECT
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </section>
            )}

            <hr className="border-slate-800/50" />

            <section className="space-y-6">
                <header>
                    <h2 className="text-xl font-bold text-white flex items-center gap-2">
                        <svg className="w-5 h-5 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                        Upgrade History
                    </h2>
                    <p className="text-slate-500 text-sm">Past approvals and rejections</p>
                </header>

                <div className="glass-panel border-slate-800/50 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="border-b border-slate-800/50 text-slate-500 text-[10px] uppercase tracking-wider">
                                    <th className="py-3 px-4 font-medium">Date</th>
                                    <th className="py-3 px-4 font-medium">User</th>
                                    <th className="py-3 px-4 font-medium">Previous Plan</th>
                                    <th className="py-3 px-4 font-medium">Requested Plan</th>
                                    <th className="py-3 px-4 font-medium">Status</th>
                                    <th className="py-3 px-4 font-medium">Proof</th>
