                <div className="mt-4 pt-4 border-t border-slate-800/20">
                    <button 
                        onClick={handleLogout}
                        className="w-full px-4 py-3 rounded-lg font-medium text-red-400 hover:bg-red-500/5 hover:text-red-300 transition-all text-left flex items-center gap-2"
                    >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                        </svg>
                        Logout
                    </button>
                </div>

                {account && !loading && (
                    <div className="mt-auto pt-6 border-t border-slate-800/50 px-2 space-y-4">
                        <div>
                            <div className="flex items-center gap-2 mb-1">
                                <span className="text-xs text-slate-400 block">Scans Remaining</span>
                                {account.scanLimitOverride !== null && account.scanLimitOverride !== undefined && (
                                    <span className="text-[9px] bg-blue-500/10 text-blue-400 px-1.5 py-0.5 rounded border border-blue-500/20 font-bold uppercase tracking-wider">Custom</span>
                                )}
                            </div>
                            <div className="flex flex-col gap-0.5">
                                <span className={`text-sm font-bold ${account.scansLeft === 0 ? 'text-red-400' : 'text-green-400'}`}>
                                    {account.scansLeft ?? 'N/A (Restart Server)'}
                                </span>
                                {(account.totalLimit && account.totalLimit !== 'Unlimited') && (
                                    <span className="text-[10px] text-slate-500">
                                        Usage: {account.websiteCount} / {account.totalLimit}
                                    </span>
                                )}
                            </div>
                        </div>
                        <div>
                            <span className="text-xs text-slate-400 block mb-1">Total Scans Performed</span>
                            <span className="text-sm font-medium text-slate-200">{account.websiteCount ?? 'N/A'}</span>
                        </div>
                    </div>
                )}
            </div>
        </aside>
    );
}

﻿"use client";
import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { API_BASE_URL } from '../../../config';

export default function AccountPage() {
    const [account, setAccount] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const router = useRouter();

    useEffect(() => {
        const fetchAccount = async () => {
            try {
                const token = localStorage.getItem('token');
                if (!token) {
                    router.push('/login');
                    return;
                }
                const res = await fetch(`${API_BASE_URL}/api/plans/current`, {
                    headers: {  
                        Authorization: `Bearer ${token}`
                    }
                });
                if (res.ok) {
                    const data = await res.json();
                    setAccount(data);
                } else {
                    setError('Failed to load account details.');
                }
            } catch (err: any) {
                console.error("Failed to fetch account info:", err);
                setError(err.message || 'Error loading data.');
            } finally {
                setLoading(false);
            }
        };

        fetchAccount();
    }, [router]);

    if (loading) {
        return (
            <div className="w-full max-w-4xl mx-auto animate-fade-in relative z-10 flex justify-center py-20">
                <div className="text-slate-400">Loading account details...</div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="w-full max-w-4xl mx-auto animate-fade-in relative z-10">
                <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-lg">{error}</div>
            </div>
        );
    }

    if (!account) return null;

    const getPlanFeatures = (planType: string) => {
        switch(planType) {
            case 'Basic Report':
                return ['Basic SEO Audit', 'Single Website Support', 'Weekly Reports', 'Community Support'];
            case 'Advanced Report':
                return ['Full SEO Audit', 'Technical SEO Checks', 'Up to 5 Websites', 'Priority Email Support', 'Keyword Tracking'];
            case 'Expert Report':
                return ['Advanced SEO Audit', 'SEO Fix Instructions', 'Performance Analysis', '25 Websites', 'Real-time Reports', '24/7 Dedicated Support', 'Competitor Analysis', 'API Access'];
            default:
                return [];
        }
    };

    return (
        <div className="w-full max-w-4xl mx-auto animate-fade-in relative z-10">
            <div className="mb-8">
                <h1 className="text-3xl font-bold text-white mb-2" style={{ fontFamily: 'var(--font-outfit)' }}>My Account</h1>
                <p className="text-slate-400">Manage your subscription and view your current plan details.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Profile Information */}
                <div className="glass-panel p-6 border-t-[3px] border-t-blue-500">
                    <h2 className="text-xl font-bold text-white mb-6 border-b border-slate-700 pb-2">Profile Information</h2>
                    <div className="space-y-4">
