﻿"use client";
import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { API_BASE_URL } from '../../../config';

export default function ScanPage() {
    const [url, setUrl] = useState('');
    const [isScanning, setIsScanning] = useState(false);
    const [error, setError] = useState('');
    const [needsUpgrade, setNeedsUpgrade] = useState(false);
    const [limitMessage, setLimitMessage] = useState('');

    const router = useRouter();

    // Re-fetch account details on mount to ensure limits are up-to-date
    useEffect(() => {
        const fetchCurrentLimits = async () => {
            try {
                const token = localStorage.getItem('token');
                await fetch(`${API_BASE_URL}/api/plans/current`, {
                    headers: { Authorization: `Bearer ${token}` }
                });
                // We don't necessarily need the data here as the Sidebar 
                // and other components will also be fetching it, 
                // but this ensures the backend 'PlanController' logs are triggered.
            } catch (err) {
                console.error("Failed to sync limits:", err);
            }
        };
        fetchCurrentLimits();
    }, []);

    const handleScan = async (e: any) => {
        e.preventDefault();
        setIsScanning(true);
        setError('');
        setNeedsUpgrade(false);

        try {
            const token = localStorage.getItem('token');
            const submitUrl = url.startsWith('http') ? url : `https://${url}`;

            const res = await fetch(`${API_BASE_URL}/api/reports/analyze`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({ url: submitUrl })
            });

            const data = await res.json();

            if (res.status === 401) {
                localStorage.removeItem('token');
                window.location.href = '/login';
                return;
            }

            if (!res.ok) {
                if (res.status === 403 && data.message === 'PLAN_LIMIT_REACHED') {
                    setNeedsUpgrade(true);
                    setLimitMessage(data.error);
                    return;
                }
                throw new Error(data.message || 'Failed to start scan');
            }

            router.push('/dashboard');
        } catch (err: any) {
            setError(err.message);
        } finally {
            setIsScanning(false);
        }
    };

    return (
        <div className="w-full max-w-3xl mx-auto animate-fade-in relative z-10 pt-10">
            {needsUpgrade ? (
                <div className="glass-panel p-8 md:p-12 text-center relative overflow-hidden">
                    <div className="absolute top-[-50px] right-[-50px] w-40 h-40 bg-purple-500/10 rounded-full blur-[50px] pointer-events-none"></div>
                    <div className="text-5xl mb-6">ðŸš€</div>
                    <h2 className="text-3xl font-bold text-white mb-4" style={{ fontFamily: 'var(--font-outfit)' }}>Plan Limit Reached</h2>
                    <p className="text-slate-400 mb-8 max-w-md mx-auto text-lg hover:text-white transition-colors">
                        {limitMessage || "Your Basic Report plan allows scanning 1 website. Upgrade your plan to Advanced Report or Expert Report to analyze more websites."}
                    </p>
                    <div className="flex gap-4 justify-center">
                        <button onClick={() => setNeedsUpgrade(false)} className="px-6 py-3 rounded-lg border border-slate-700 text-slate-300 hover:bg-slate-800 hover:text-white transition-colors cursor-pointer font-medium">
                            <span className="relative z-10">Go Back</span>
                        </button>
                        <button onClick={() => router.push('/plans')} className="px-6 py-3 rounded-lg bg-gradient-to-r from-purple-600 to-blue-600 hover:from-purple-500 hover:to-blue-500 text-white font-bold shadow-[0_0_20px_rgba(168,85,247,0.3)] hover:shadow-[0_0_30px_rgba(168,85,247,0.5)] transition-all transform hover:-translate-y-0.5 cursor-pointer flex items-center gap-2">
                            <span>Upgrade Plan</span>
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                        </button>
                    </div>
                </div>
            ) : (
                <div className="glass-panel p-8 md:p-12 relative overflow-hidden">
                    <div className="absolute top-[-50px] right-[-50px] w-40 h-40 bg-blue-500/10 rounded-full blur-[50px] pointer-events-none"></div>

                    <div className="text-center mb-10 relative z-10">
                        <h1 className="text-3xl font-bold text-white mb-3" style={{ fontFamily: 'var(--font-outfit)' }}>Start New SEO Audit</h1>
                        <p className="text-slate-400">Enter your website URL below to begin a comprehensive technical and on-page analysis.</p>
                    </div>

                    {error && <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-lg mb-6 text-sm relative z-10 text-center">{error}</div>}

                    <form onSubmit={handleScan} className="relative z-10">
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-slate-300 mb-2">Website URL</label>
                            <div className="flex bg-slate-900/50 border border-slate-700/50 rounded-lg overflow-hidden focus-within:ring-2 focus-within:ring-blue-500/50 focus-within:border-transparent transition-all shadow-inner">
                                <span className="flex items-center justify-center px-4 bg-slate-800/50 text-slate-500 font-medium">https://</span>
                                <input
                                    type="text"
                                    value={url}
                                    onChange={(e) => setUrl(e.target.value)}
                                    className="flex-1 bg-transparent px-4 py-4 text-white placeholder-slate-500 focus:outline-none"
                                    placeholder="example.com"
                                    required
                                />
                            </div>
                        </div>

                        <button
                            type="submit"
                            disabled={isScanning}
                            className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold py-4 px-4 rounded-lg shadow-[0_0_20px_rgba(59,130,246,0.3)] hover:shadow-[0_0_30px_rgba(59,130,246,0.5)] transform hover:-translate-y-0.5 transition-all duration-300 disabled:opacity-70 disabled:cursor-not-allowed flex justify-center items-center cursor-pointer"
                        >
                            {isScanning ? (
                                <><svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg> Running crawler...</>
                            ) : "Run Full Scan"}
                        </button>
                    </form>
                </div>
            )}
        </div>
    );
}

"use client";
import Link from 'next/link';
import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { API_BASE_URL } from '../../config';

export default function LoginPage() {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const router = useRouter();

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        try {
            const res = await fetch(`${API_BASE_URL}/api/auth/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, password }),
            });
            const data = await res.json();

            if (!res.ok) {
                throw new Error(data.message || 'Invalid credentials');
            }

            // Save token and redirect
            localStorage.setItem('token', data.token);

            // Check for pre-selected plan from /plans page
            const selectedPlan = localStorage.getItem('selected_plan');
            if (selectedPlan) {
                try {
                    await fetch(`${API_BASE_URL}/api/plans/select`, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Authorization': `Bearer ${data.token}`
                        },
                        body: JSON.stringify({ planType: selectedPlan }),
                    });
                    localStorage.removeItem('selected_plan');
                } catch (planError) {
                    console.error("Failed to apply pre-selected plan:", planError);
                }
                router.push('/dashboard');
                return;
            }

            if (data.hasPlan) {
                router.push('/dashboard');
            } else {
                router.push('/plans');
            }
        } catch (err: any) {
            console.error("Login error:", err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-[80vh] px-4">
            <div className="glass-panel w-full max-w-md p-8 md:p-10 animate-fade-in relative overflow-hidden">
                {/* Decorative background blur */}
                <div className="absolute top-[-50px] right-[-50px] w-40 h-40 bg-blue-500/20 rounded-full blur-[50px] pointer-events-none"></div>
                <div className="absolute bottom-[-50px] left-[-50px] w-40 h-40 bg-violet-500/20 rounded-full blur-[50px] pointer-events-none"></div>

                <div className="text-center mb-10 relative z-10">
                    <h2 className="text-3xl font-bold text-white mb-2" style={{ fontFamily: 'var(--font-outfit)' }}>Welcome Back</h2>
                    <p className="text-slate-400">Sign in to access your SEO reports.</p>
                </div>

                {error && <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-lg mb-6 text-sm relative z-10">{error}</div>}

                <form onSubmit={handleSubmit} className="space-y-6 relative z-10">
                    <div>
                        <label className="block text-sm font-medium text-slate-300 mb-2">Email address</label>
                        <input
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            className="w-full bg-slate-900/50 border border-slate-700/50 rounded-lg px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-transparent transition-all shadow-inner"
                            placeholder="you@example.com"
                            required
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-300 mb-2">Password</label>
                        <input
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full bg-slate-900/50 border border-slate-700/50 rounded-lg px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-transparent transition-all shadow-inner"
                            placeholder="â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢"
                            required
                        />
                    </div>

                    <div className="flex items-center justify-between">
                        <label className="flex items-center text-sm text-slate-300 cursor-pointer">
                            <input type="checkbox" className="form-checkbox bg-slate-800 border-slate-600 rounded text-blue-500 focus:ring-blue-500 focus:ring-offset-slate-900 mr-2" />
                            Remember me
                        </label>
                        <a href="#" className="flex-shrink-0 text-sm font-medium text-blue-400 hover:text-blue-300 transition-colors">Forgot password?</a>
                    </div>

                    <button disabled={loading} type="submit" className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-semibold py-3 px-4 rounded-lg shadow-[0_0_20px_rgba(59,130,246,0.3)] hover:shadow-[0_0_25px_rgba(59,130,246,0.5)] transform hover:-translate-y-0.5 transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed">
                        {loading ? 'Signing in...' : 'Sign In'}
                    </button>
                </form>

                <div className="mt-8 text-center text-sm text-slate-400 relative z-10">
                    Don't have an account?{' '}
                    <Link prefetch={false} href="/register" className="font-semibold text-blue-400 hover:text-blue-300 transition-colors">
                        Sign up
                    </Link>
                </div>
            </div>
        </div>
    );
}

﻿"use client";
import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { API_BASE_URL } from '../../config';

const plans = [
    {
        name: 'Basic Report',
        price: 'Free',
        description: 'Perfect for small websites looking to get started with SEO.',
        features: ['Basic SEO Audit', 'Single Website Support', 'Weekly Reports', 'Community Support'],
        gradient: 'from-blue-500/20 to-cyan-500/20',
        border: 'border-blue-500/30',
        buttonClass: 'bg-blue-600 hover:bg-blue-500'
    },
    {
        name: 'Advanced Report',
        price: '$29/mo',
        description: 'Best for growing businesses needing deeper insights.',
        features: ['Full SEO Audit', 'Up to 5 Websites',  'Priority Email Support', 'Keyword Tracking'],
        gradient: 'from-indigo-500/20 to-purple-500/20',
        border: 'border-indigo-500/50',
        buttonClass: 'bg-indigo-600 hover:bg-indigo-500',
        popular: true
    },
    {
        name: 'Expert Report',
        price: '$99/mo',
        description: 'Comprehensive analysis for agencies and large enterprises.',
        features: ['Advanced SEO Audit', '25 Websites', 'Real-time Reports', '24/7 Dedicated Support', 'Competitor Analysis', 'API Access'],
        gradient: 'from-amber-600/20 to-orange-600/20',
        border: 'border-amber-500/30',
        buttonClass: 'bg-amber-600 hover:bg-amber-500'
    }
];

export default function PlansPage() {
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [showPayment, setShowPayment] = useState(false);
    const [selectedPremiumPlan, setSelectedPremiumPlan] = useState('');
    const [paymentMethod, setPaymentMethod] = useState('');
    const [receipt, setReceipt] = useState<File | null>(null);
    const [isSubmitted, setIsSubmitted] = useState(false);
    const router = useRouter();

    const initiatePlanSelection = (planName: string) => {
        if (planName === 'Basic Report') {
            handleSelectPlan(planName);
        } else {
            setSelectedPremiumPlan(planName);
            setShowPayment(true);
            setError('');
        }
    };

    const handlePayment = (e: React.FormEvent) => {
        e.preventDefault();
        if (!paymentMethod) {
            setError('Please select a payment method');
            return;
        }
        if (paymentMethod === 'bank' && !receipt) {
            setError('Please upload your payment receipt');
            return;
        }
        handleSelectPlan(selectedPremiumPlan, receipt);
    };

    // No longer forced to login to view plans

    const handleSelectPlan = async (planName: string, receiptFile: File | null = null) => {
        setLoading(true);
        setError('');
        const token = localStorage.getItem('token');
        if (!token) {
            localStorage.setItem('selected_plan', planName);
            router.push('/login');
            return;
        }

        try {
            const formData = new FormData();
            formData.append('planType', planName);
            if (receiptFile) {
                formData.append('receipt', receiptFile);
            }

            const res = await fetch(`${API_BASE_URL}/api/plans/select`, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${token}`
                    // Note: Browser will automatically set multipart/form-data boundary
                },
                body: formData,
            });

            const contentType = res.headers.get('content-type');
            if (contentType && contentType.includes('application/json')) {
                const data = await res.json();
                if (!res.ok) {
                    throw new Error(data.message || 'Failed to select plan');
                }
                
                if (receiptFile) {
                    setIsSubmitted(true);
                    setShowPayment(false);
                } else {
                    router.push('/dashboard');
                }
            } else {
                const text = await res.text();
                console.error('[PlansPage] Non-JSON response received:', text.substring(0, 200));
                throw new Error('Server returned an invalid response. Please check your connection or contact support.');
            }
        } catch (err: any) {
            console.error("Plan selection error:", err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen py-20 px-4 flex flex-col items-center justify-center">
            <div className="max-w-6xl w-full text-center mb-16 animate-fade-in">
                <h1 className="text-4xl md:text-5xl font-bold text-white mb-6" style={{ fontFamily: 'var(--font-outfit)' }}>
                    {showPayment ? 'Complete Your Payment' : <>Choose Your <span className="text-blue-400">SEO Service Plan</span></>}
                </h1>
                <p className="text-slate-400 text-lg max-w-2xl mx-auto">
                    {showPayment ? `You have selected the ${selectedPremiumPlan}. Securely pay to activate your new limits.` : 'Select a plan that fits your business needs. You can change your plan at any time from your account settings.'}
                </p>
                {error && <div className="mt-8 bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-lg text-sm max-w-md mx-auto">{error}</div>}
                {isSubmitted && <div className="mt-8 bg-green-500/10 border border-green-500/20 text-green-400 p-4 rounded-lg text-sm max-w-md mx-auto font-medium">Your request has been submitted! Your upgradation will be approved by admin soon.</div>}
            </div>

            {showPayment ? (
